import React, { useState } from "react";
import AchievementsPanel from './AchievementsPanel';

export default function AdminDashboard({ reports, token, setMsg }) {
  const [ngos, setNgos] = useState(null);
  const [events, setEvents] = useState(null);
  const [eventStats, setEventStats] = useState(null);

  const API = process.env.REACT_APP_API || "http://localhost:4000";

  // Generic fetch handler
  const loadData = async (endpoint, setter, field, errMsg) => {
    if (!token) return setMsg("Login as admin first");
    try {
      const res = await fetch(`${API}${endpoint}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) throw new Error(errMsg);
      const data = await res.json();

      setter(data[field] || []);
    } catch (e) {
      console.error(e);
      setMsg(e.message || errMsg);
    }
  };

  // ✅ NEW — Delete NGO
  const deleteNgo = async (id) => {
    if (!token) return setMsg("Login as admin first");

    if (!window.confirm("Are you sure you want to remove this NGO?")) return;

    try {
      const res = await fetch(`${API}/api/actions/remove-ngo/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) throw new Error("Failed to delete NGO");

      setMsg("NGO removed successfully");
      setNgos((prev) => prev.filter((n) => n.id !== id)); // update UI instantly
    } catch (e) {
      console.error(e);
      setMsg(e.message);
    }
  };

  return (
    <div className="panel" style={{ display: 'flex', gap: 16 }}>

      <AchievementsPanel token={token} me={{ points: (reports?.adminPoints || 0) }} role={'user'} setMsg={setMsg} />

      <div style={{ flex: 1 }}>
      <h3>Admin Reports</h3>

      <div className="cards">
        <div className="stat-card">
          <div className="stat-num">
            {reports?.donations
              ? reports.donations.reduce((s, d) => s + parseFloat(d.amount || 0), 0)
              : "-"}
          </div>
          <div className="stat-label">Total Donation Amount (₹)</div>
        </div>

        <div className="stat-card">
          <div className="stat-num">{reports?.volunteers?.length || 0}</div>
          <div className="stat-label">Total Volunteers</div>
        </div>

        <div className="stat-card">
          <div className="stat-num">{reports?.feedbacks?.length || 0}</div>
          <div className="stat-label">Feedbacks</div>
        </div>
      </div>

      {/* ACTION BUTTONS */}
      <div style={{ marginTop: 12 }}>
        {/* NGOs */}
        <button
          onClick={() =>
            loadData("/api/actions/ngos", setNgos, "ngos", "Failed to load NGOs")
          }
        >
          View Registered NGOs
        </button>

        {/* EVENTS */}
        <button
          style={{ marginLeft: 8 }}
          onClick={() =>
            loadData(
              "/api/actions/registered-events",
              setEvents,
              "events",
              "Failed to load events"
            )
          }
        >
          View Registered Events
        </button>

        {/* EVENT STATS */}
        <button
          style={{ marginLeft: 8 }}
          onClick={() =>
            loadData(
              "/api/actions/event-stats",
              setEventStats,
              "events",
              "Failed to load event stats"
            )
          }
        >
          View Event Stats
        </button>
      </div>

      {/* EVENT LIST */}
      {events && (
        <div style={{ marginTop: 20 }}>
          <h4>Registered Events</h4>
          {events.length ? (
            events.map((e) => (
              <div
                key={e.id}
                style={{
                  padding: 8,
                  background: "#fff",
                  borderRadius: 8,
                  marginBottom: 8,
                }}
              >
                <strong>{e.title}</strong>
                <div style={{ fontSize: 13, color: "#666" }}>{e.date}</div>
              </div>
            ))
          ) : (
            <p>No events registered.</p>
          )}
        </div>
      )}

      {/* EVENT STATS */}
      {eventStats && (
        <div style={{ width: 420, marginTop: 20 }}>
          <h4>Event Statistics</h4>
          {eventStats.length ? (
            eventStats.map((ev) => (
              <div
                key={ev.id}
                style={{
                  display: "flex",
                  gap: 12,
                  alignItems: "center",
                  padding: 8,
                  background: "#fff",
                  borderRadius: 8,
                  marginBottom: 8,
                }}
              >
                <img
                  src={ev.image_url || "https://via.placeholder.com/120x80"}
                  alt="ev"
                  style={{ width: 100, height: 64, objectFit: "cover", borderRadius: 6 }}
                />
                <div style={{ flex: 1 }}>
                  <div style={{ fontWeight: 600 }}>{ev.title}</div>
                  <div style={{ fontSize: 13, color: "#666" }}>
                    Volunteers: {ev.volunteers_count} — Donations: ₹{ev.donations_sum}
                  </div>
                </div>
              </div>
            ))
          ) : (
            <p>No event statistics loaded.</p>
          )}
        </div>
      )}

      {/* NGO LIST */}
      {ngos && (
        <div style={{ marginTop: 20 }}>
          <h4>Registered NGOs</h4>
          {ngos.length ? (
            ngos.map((n) => (
              <div
                key={n.id}
                style={{
                  padding: 8,
                  background: "#fff",
                  borderRadius: 8,
                  marginBottom: 8,
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                }}
              >
                <div>
                  <strong>{n.name}</strong>
                  <div style={{ fontSize: 13, color: "#666" }}>{n.email}</div>
                </div>

                {/* ✅ NEW REMOVE BUTTON */}
                <button
                  style={{
                    padding: "6px 12px",
                    background: "red",
                    color: "white",
                    border: "none",
                    borderRadius: 6,
                    cursor: "pointer",
                  }}
                  onClick={() => deleteNgo(n.id)}
                >
                  Remove
                </button>
              </div>
            ))
          ) : (
            <p>No NGOs registered.</p>
          )}
        </div>
      )}
      </div>

      {/* RIGHT: Quick actions */}
      <div style={{ width: 320, flexShrink: 0 }}>
        <div style={{ background: '#fff', padding: 12, borderRadius: 10, boxShadow: '0 6px 20px rgba(2,6,23,0.04)' }}>
          <h4>Quick Actions</h4>
          <button onClick={() => loadData('/api/actions/ngos', setNgos, 'ngos', 'Failed to load NGOs')} style={{ width: '100%', padding: 10, borderRadius: 8, marginBottom: 8 }}>View NGOs</button>
          <button onClick={() => loadData('/api/actions/registered-events', setEvents, 'events', 'Failed to load events')} style={{ width: '100%', padding: 10, borderRadius: 8, marginBottom: 8 }}>View Events</button>
          <button onClick={() => loadData('/api/actions/event-stats', setEventStats, 'events', 'Failed to load stats')} style={{ width: '100%', padding: 10, borderRadius: 8 }}>Event Stats</button>
        </div>
      </div>
    </div>
  );
}
